import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int L = sc.nextInt();
        int C = sc.nextInt();
        int P = sc.nextInt();

        boolean[][] black = new boolean[L][C];

        for (int i = 0; i < P; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            black[x][y] = true;
        }

        int[] valid = new int[L];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < L; r++) {
            for (int c = 0; c < C; c++) {
                if (black[r][c]) continue;

                boolean canBeWhite = false;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];

                    if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                        canBeWhite = true;
                        break;
                    }
                }

                if (canBeWhite) {
                    valid[r] |= (1 << c);
                }
            }
        }

        int M = 1 << C;
        int NEG = -1000000;

        int[] dp = new int[M];
        Arrays.fill(dp, NEG);
        dp[0] = 0;

        for (int r = 0; r < L; r++) {
            int[] next = new int[M];
            Arrays.fill(next, NEG);

            for (int prev = 0; prev < M; prev++) {
                if (dp[prev] < 0) continue;

                for (int cur = 0; cur < M; cur++) {
                    if ((cur & ~valid[r]) != 0) continue;
                    if ((cur & (cur << 1)) != 0) continue;
                    if ((cur & prev) != 0) continue;

                    int val = dp[prev] + Integer.bitCount(cur);
                    if (val > next[cur]) {
                        next[cur] = val;
                    }
                }
            }

            dp = next;
        }

        int answer = 0;
        for (int v : dp) {
            answer = Math.max(answer, v);
        }

        System.out.println(answer);
    }
}
